package com.himeros.premium;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity@Table(name="subscriptions")class Subscription{enum Status{ACTIVE,EXPIRED,CANCELLED}@Id private UUID id;@Column(name="user_id",nullable=false)private UUID userId;@Column(nullable=false)private String plan;@Enumerated(EnumType.STRING)@Column(nullable=false)private Status status;@Column(name="starts_at",nullable=false)private Instant startsAt;@Column(name="ends_at",nullable=false)private Instant endsAt;@Column(name="payment_id")private UUID paymentId;@Column(name="created_at",nullable=false)private Instant createdAt;protected Subscription(){}Subscription(UUID user,String plan,UUID payment,Instant start,Instant end){id=UUID.randomUUID();userId=user;this.plan=plan;paymentId=payment;startsAt=start;endsAt=end;status=Status.ACTIVE;createdAt=Instant.now();}UUID id(){return id;}UUID user(){return userId;}String plan(){return plan;}Status status(){return status;}Instant starts(){return startsAt;}Instant ends(){return endsAt;}UUID payment(){return paymentId;}}
